/** Splits each dotted path into nested packages, sharing every ancestor already seen. */
function buildTree(records: FlatModule[]): ModuleNode {
  const root: ModuleNode = { name: 'gallery', children: [] };
  const byPath = new Map<string, ModuleNode>([[root.name, root]]);

  for (const record of records) {
    const parts = record.name.split('.');
    let parent = root;
    for (let depth = 1; depth < parts.length; depth++) {
      const path = parts.slice(0, depth + 1).join('.');
      let node = byPath.get(path);
      if (!node) {
        node = { name: parts[depth] };
        byPath.set(path, node);
        (parent.children ??= []).push(node);
      }
      parent = node;
    }
    parent.imports = record.imports;
  }
  return root;
}

const moduleTree: ModuleNode = buildTree(modules);

/** A tree whose leaves name the other leaves they point at, by dotted path from the root. */
export type Data = { name: string; children?: Data[]; imports?: string[] };

type Node = d3.HierarchyPointNode<Data>;
type Point = [number, number];
type Flow = { out: number; in: number };

/** Radial band reserved outside the layout for the leaf labels. */
const LABEL_ROOM = 108;
const FONT_SIZE = 10;
/** Mean advance width of 10px sans-serif, used to drop labels that would overflow. */
const CHAR_WIDTH = 5.6;
const LABEL_GAP = 6;
const SEGMENTS = 64;
const BETA = 0.85;

/** Dim in the middle so the two ends carry the eye, the dark-ground analogue of RdBu on white. */
const edgeColor = d3.interpolateRgbBasis(['#5eb3f6', '#3a4046', '#f5714a']);
/** Same hues, legible mid: a balanced node must still be visible at r=2. */
const nodeColor = d3.interpolateRgbBasis(['#5eb3f6', '#8b8f94', '#f5714a']);

function idOf(node: Node): string {
  return `${node.parent ? `${idOf(node.parent)}.` : ''}${node.data.name}`;
}

/** d3.lineRadial's convention: angle 0 points up and increases clockwise. */
function toCartesian(node: Node): Point {
  return [node.y * Math.sin(node.x), -node.y * Math.cos(node.x)];
}

/** d3.curveBundle's beta blend: pull each waypoint toward the straight source-target chord. */
function bundle(points: Point[]): Point[] {
  const last = points.length - 1;
  const [x0, y0] = points[0];
  const [x1, y1] = points[last];
  return points.map(([x, y], i): Point => {
    const t = last === 0 ? 0 : i / last;
    return [
      BETA * x + (1 - BETA) * (x0 + t * (x1 - x0)),
      BETA * y + (1 - BETA) * (y0 + t * (y1 - y0))
    ];
  });
}

/**
 * Uniform cubic B-spline (what d3.curveBasis draws) sampled at evenly spaced parameters.
 * Sampling rather than emitting one path is what lets each piece take its own color.
 */
function sampleBasis(points: Point[]): Point[] {
  const first = points[0];
  const last = points[points.length - 1];
  const control = [first, first, ...points, last, last];
  const spans = control.length - 3;
  return d3.range(SEGMENTS + 1).map((step): Point => {
    const u = (step / SEGMENTS) * spans;
    const span = Math.min(Math.floor(u), spans - 1);
    const t = u - span;
    const b = [
      (1 - t) ** 3 / 6,
      (3 * t ** 3 - 6 * t ** 2 + 4) / 6,
      (-3 * t ** 3 + 3 * t ** 2 + 3 * t + 1) / 6,
      t ** 3 / 6
    ];
    return [
      b.reduce((sum, w, k) => sum + w * control[span + k][0], 0),
      b.reduce((sum, w, k) => sum + w * control[span + k][1], 0)
    ];
  });
}

const round = (value: number) => Math.round(value * 10) / 10;

export default function EdgeBundlingBilevel({ data = moduleTree, width }:
  { data?: Data; width: number }) {
  const height = width;
  const radius = width / 2;
  const innerRadius = Math.max(radius - LABEL_ROOM, 20);

  const { leaves, strokes, flow } = useMemo(() => {
    const hierarchy = d3
      .hierarchy(data)
      .sort(
        (a, b) =>
          d3.ascending(a.height, b.height) || d3.ascending(a.data.name, b.data.name)
      );
    const root = d3.cluster<Data>().size([2 * Math.PI, innerRadius])(hierarchy);
    const nodes = root.leaves();
    const byId = new Map(nodes.map((leaf) => [idOf(leaf), leaf]));
    const flow = new Map<string, Flow>(nodes.map((leaf) => [idOf(leaf), { out: 0, in: 0 }]));

    // Every edge routes through its endpoints' least common ancestor, then gets sampled
    // so the i-th piece of every curve can share one path element per color stop.
    const curves = nodes.flatMap((source) =>
      (source.data.imports ?? []).flatMap((importId) => {
        const target = byId.get(importId);
        if (!target) return [];
        flow.get(idOf(source))!.out += 1;
        flow.get(importId)!.in += 1;
        return [sampleBasis(bundle(source.path(target).map(toCartesian)))];
      })
    );

    const strokes = d3.range(SEGMENTS).map((i) =>
      curves
        .map(
          (samples) =>
            `M${round(samples[i][0])},${round(samples[i][1])}` +
            `L${round(samples[i + 1][0])},${round(samples[i + 1][1])}`
        )
        .join('')
    );

    return { leaves: nodes, strokes, flow };
  }, [data, innerRadius]);

  const labelRoom = radius - innerRadius - LABEL_GAP * 2;

  if (width === 0) return null;

  return (
    <svg
      viewBox={`${-radius} ${-radius} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Hierarchical edge bundling of module imports, each curve colored along its length from the importing module in blue to the imported module in red"
    >
      <g fill="none" strokeWidth={1} strokeOpacity={0.55} style={{ mixBlendMode: 'screen' }}>
        {strokes.map((d, i) => (
          <path key={i} d={d} stroke={edgeColor(d3.easeQuad(i / (SEGMENTS - 1)))} />
        ))}
      </g>
      <g fontSize={FONT_SIZE}>
        {leaves.map((leaf) => {
          const id = idOf(leaf);
          const { out, in: inbound } = flow.get(id)!;
          const degree = out + inbound;
          const flipped = leaf.x >= Math.PI;
          const fits = leaf.data.name.length * CHAR_WIDTH < labelRoom;
          return (
            <g
              key={id}
              transform={`rotate(${(leaf.x * 180) / Math.PI - 90}) translate(${leaf.y},0)`}
            >
              <title>{`${id}\n${out} imported, ${inbound} importers`}</title>
              <circle
                r={degree === 0 ? 1.6 : 2.4}
                fill={degree === 0 ? 'var(--muted)' : nodeColor(inbound / degree)}
              />
              {fits && (
                <text
                  dy="0.31em"
                  x={flipped ? -LABEL_GAP : LABEL_GAP}
                  textAnchor={flipped ? 'end' : 'start'}
                  transform={flipped ? 'rotate(180)' : undefined}
                  fill="var(--text)"
                >
                  {leaf.data.name}
                </text>
              )}
            </g>
          );
        })}
      </g>
      {width >= 420 && (
        <g transform={`translate(${-radius + 14},${-radius + 16})`} fontSize={FONT_SIZE}>
          <text fill="var(--muted)">each edge runs importer to imported</text>
          {d3.range(30).map((i) => (
            <rect key={i} x={i * 4} y={7} width={4} height={7} fill={edgeColor(i / 29)} />
          ))}
          <text y={26} fill="#5eb3f6">
            importer
          </text>
          <text x={120} y={26} textAnchor="end" fill="#f5714a">
            imported
          </text>
        </g>
      )}
    </svg>
  );
}
